#!/usr/bin/env python3
"""
applications.py — Real-World Applications of Local Cycle Pressure

Demonstrates practical applications of cycle pressure theory to:
1. Proof dependency graph analysis
2. Theorem difficulty prediction
3. Feature extraction for proof-guidance ML
4. Graph complexity stratification
"""

from collections import defaultdict, deque
from typing import Set, Dict, List, Tuple
import random


# ── Core algorithms (inlined for self-containment) ──
from collections import defaultdict, deque

def induced_edge_count(adj, vertices, subset):
    subset = set(subset)
    count = 0
    seen = set()
    for u in subset:
        for v in adj.get(u, set()):
            if v in subset:
                edge = frozenset({u, v})
                if edge not in seen:
                    seen.add(edge)
                    count += 1
    return count

def subset_cycle_rank(adj, vertices, subset):
    subset = set(subset)
    return induced_edge_count(adj, vertices, subset) - len(subset) + 1

def graph_cycle_rank(adj, vertices):
    edge_count = sum(len(adj.get(v, set())) for v in vertices) // 2
    return edge_count - len(vertices) + 1

def geodesic_ball(adj, v, r):
    dist = {v: 0}
    queue = deque([v])
    while queue:
        u = queue.popleft()
        if dist[u] >= r: continue
        for w in adj.get(u, set()):
            if w not in dist:
                dist[w] = dist[u] + 1
                queue.append(w)
    return set(dist.keys())

def local_cycle_pressure(adj, vertices, v, r):
    ball = geodesic_ball(adj, v, r)
    return subset_cycle_rank(adj, vertices, ball)

def cycle_aware_score(adj, vertices, v):
    closed_nbhd = {v} | adj.get(v, set())
    return subset_cycle_rank(adj, vertices, closed_nbhd)

def pressure_profile(adj, vertices, v, max_radius=None):
    if max_radius is None: max_radius = len(vertices)
    profile = []
    for r in range(max_radius + 1):
        ball = geodesic_ball(adj, v, r)
        ec = induced_edge_count(adj, vertices, ball)
        cp = ec - len(ball) + 1
        profile.append((r, len(ball), ec, cp))
    return profile

def connected_components(adj, vertices):
    visited = set()
    count = 0
    for v in vertices:
        if v not in visited:
            count += 1
            queue = deque([v])
            while queue:
                u = queue.popleft()
                if u in visited: continue
                visited.add(u)
                for w in adj.get(u, set()):
                    if w not in visited: queue.append(w)
    return count

def collapse_entropy_proxy(adj, vertices):
    edge_count = sum(len(adj.get(v, set())) for v in vertices) // 2
    c = connected_components(adj, vertices)
    return edge_count - len(vertices) + c

