function LocalCyclePressure(G, v, r):
    S ← BFS(G, v, r)     // geodesic ball
    E ← InducedEdgeCount(G, S)
    return E - |S| + 1

function InducedEdgeCount(G, S):
    count ← 0
    for each edge {u, v} ∈ E(G):
        if u ∈ S and v ∈ S:
            count ← count + 1
    return count

function CycleAwareScore(G, v):
    N ← {v} ∪ neighbors(v)
    return InducedEdgeCount(G, N) - |N| + 1

